<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
$root='/var/www/vhosts/shalean.com/faraios.com';
$private='/var/www/vhosts/shalean.com/private/faraios-account';
$payload=json_decode(gzdecode(base64_decode('',true)),true,512,JSON_THROW_ON_ERROR);
$mode=$argv[1]??'--check';if(!in_array($mode,['--check','--apply'],true))throw new RuntimeException('Use --check or --apply');
$lock=fopen($private.'/seo-release.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new RuntimeException('Release locked');chmod($private.'/seo-release.lock',0600);
$changes=[];$drift=[];
foreach($payload as $p=>$v){$h=hash_file('sha256',$root.'/'.$p);if($h===$v['candidate_sha256'])continue;if($h!==$v['baseline_sha256'])$drift[]=$p;else $changes[]=$p;if(hash('sha256',base64_decode($v['content'],true))!==$v['candidate_sha256'])throw new RuntimeException('Corrupt payload');}
if($drift){echo json_encode(['seo_release'=>'STOP','drift'=>$drift]);exit(1);}
if($mode==='--check'){echo json_encode(['seo_release'=>'preflight_PASS','files'=>count($payload),'pending'=>count($changes),'database_writes'=>false]);exit;}
if(!$changes){echo json_encode(['seo_release'=>'already_applied','files'=>count($payload)]);exit;}
$backup=$private.'/seo-release-'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(3));if(!mkdir($backup,0700))throw new RuntimeException('Backup failed');
$protected=[];foreach(glob($root.'/account/*') as $f)if(is_file($f))$protected[$f]=hash_file('sha256',$f);
foreach(['config.php','production.php'] as $f)if(is_file($private.'/'.$f))$protected[$private.'/'.$f]=hash_file('sha256',$private.'/'.$f);
$written=[];
try{
 foreach($changes as $p){$dest=$root.'/'.$p;$v=$payload[$p];if(hash_file('sha256',$dest)!==$v['baseline_sha256'])throw new RuntimeException('Concurrent change: '.$p);$saved=$backup.'/'.str_replace('/','__',$p);if(!copy($dest,$saved)||!chmod($saved,0600))throw new RuntimeException('Backup failed');}
 foreach($changes as $p){$dest=$root.'/'.$p;$v=$payload[$p];if(hash_file('sha256',$dest)!==$v['baseline_sha256'])throw new RuntimeException('Concurrent change: '.$p);$tmp=$dest.'.seo-'.bin2hex(random_bytes(4));if(file_put_contents($tmp,base64_decode($v['content'],true),LOCK_EX)===false||!chmod($tmp,fileperms($dest)&0777))throw new RuntimeException('Stage failed');if(!rename($tmp,$dest))throw new RuntimeException('Install failed');$written[]=$p;if(function_exists('opcache_invalidate'))opcache_invalidate($dest,true);}
 foreach($protected as $f=>$h)if(hash_file('sha256',$f)!==$h)throw new RuntimeException('Protected file changed');
 $receipt=['seo_release'=>'applied_PASS','files'=>count($payload),'changed'=>count($changes),'protected_files'=>count($protected),'database_writes'=>false,'backup'=>basename($backup),'time'=>gmdate('c')];file_put_contents($backup.'/receipt.json',json_encode($receipt));chmod($backup.'/receipt.json',0600);echo json_encode($receipt);
}catch(Throwable $e){foreach(array_reverse($written) as $p){if(hash_file('sha256',$root.'/'.$p)===$payload[$p]['candidate_sha256'])copy($backup.'/'.str_replace('/','__',$p),$root.'/'.$p);}throw $e;}
